fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){assert!(!Path::new(&format!("{R}/checkpoint.json")).exists());let a=read(format!("{R}/source-audit.json"));let m=read(a["base_manifest"].as_str().unwrap());assert_eq!(hash(a["base_manifest"].as_str().unwrap()),a["base_manifest_sha256"]);let base=m["source_files_sha256"].as_object().unwrap();let mut changes=BTreeMap::new();
for(rel,h)in base{let p=format!("{R}/source/{rel}");if hash(&p)!=h.as_str().unwrap(){changes.insert(rel.clone(),hash(&p));}}
assert_eq!(changes.len(),2);let e=&a["reversible_parent_edit"];let parent=e["file"].as_str().unwrap();let body=fs::read_to_string(format!("{R}/source/{parent}")).unwrap();let b=body.strip_suffix(e["suffix"].as_str().unwrap()).unwrap();assert_eq!(b.matches(e["new"].as_str().unwrap()).count(),1);assert_eq!(format!("{:x}",Sha256::digest(b.replace(e["new"].as_str().unwrap(),e["old"].as_str().unwrap()).as_bytes())),base[parent]);
let p="crates/zopro-core/src/msm.rs";let text=fs::read_to_string(format!("{R}/source/{p}")).unwrap();assert_eq!(format!("{:x}",Sha256::digest(text.strip_suffix(a["test_only_msm_suffix"].as_str().unwrap()).unwrap().as_bytes())),base[p]);
let mut commands=0;for(plan,folder)in[("candidate-plan.json","native-candidate"),("control-plan.json","native-control"),("portable-plan.json","portable")]{assert_eq!(read(format!("{R}/{folder}/result.json"))["status"],"complete");for s in read(format!("{R}/{plan}"))["steps"].as_array().unwrap(){let p=format!("{R}/{folder}/{}",s["name"].as_str().unwrap());let exit=read(format!("{p}/exit.json"));assert_eq!(exit["success"],true);assert_eq!(exit["returncode"],0);for stream in["stdout","stderr"]{assert_eq!(hash(format!("{p}/{stream}.log")),exit[format!("{stream}_sha256")]);}let c=read(format!("{p}/command.json"));assert_eq!(&c["argv"].as_array().unwrap()[4..],s["argv"].as_array().unwrap());for(k,v)in s["environment"].as_object().into_iter().flatten(){if !["PATH","RUSTC","RUSTUP_TOOLCHAIN"].contains(&k.as_str()){assert_eq!(c["environment"][k],*v);}}commands+=1;}}
for(folder,step,count)in[("native-candidate","candidate-core",130),("portable","portable-core",97)]{let text=fs::read_to_string(format!("{R}/{folder}/{step}/stdout.log")).unwrap();assert!(text.contains(&format!("test result: ok. {count} passed; 0 failed; 0 ignored; 0 measured; 0 filtered out")));let tests=read(format!("{R}/{folder}/{step}/tests.json"));assert_eq!(tests["passed_tests"].as_array().unwrap().len(),count);}
let prover=fs::read_to_string(format!("{R}/native-candidate/candidate-prover/stdout.log")).unwrap();for n in[2,6]{assert!(prover.contains(&format!("test result: ok. {n} passed; 0 failed; 0 ignored; 0 measured; 0 filtered out")));}
let mut consumers=Vec::new();let mut sizes=BTreeMap::new();for label in["control","candidate"]{let f=read(format!("{R}/frozen-{label}.json"));assert_eq!(f["libraries"].as_object().unwrap().len(),8);assert_eq!(f["rustflags"].as_str().unwrap().contains("--cfg zopro_g2_coordinate_leaf"),label=="candidate");for(p,h)in f["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let l=read(format!("{R}/link-{label}.json"));assert_eq!(l["success"],true);assert_eq!(l["exit_code"],0);for stream in["stdout","stderr"]{assert_eq!(hash(format!("{R}/link-{label}.{stream}")),l[format!("{stream}_sha256")]);}
let binary=format!("{R}/sdk-{label}-znver4");let o=Command::new("nm").args(["-S","--defined-only",&binary]).output().unwrap();assert!(o.status.success());fs::write(format!("{R}/{label}-symbols.txt"),&o.stdout).unwrap();let text=String::from_utf8(o.stdout).unwrap();let mut selected=Vec::new();for line in text.lines().filter(|s|s.contains("3msm11g2_borrowed5apply")||s.contains("coordinate_leaf6finish")){let p=line.split_whitespace().collect::<Vec<_>>();selected.push(json!({"name":p[3],"address":u64::from_str_radix(p[0],16).unwrap(),"bytes":u64::from_str_radix(p[1],16).unwrap()}));}assert_eq!(selected.len(),if label=="candidate"{2}else{1});sizes.insert(label.to_string(),selected);
consumers.push(json!({"label":label,"path":binary,"sha256":hash(&binary),"frozen_metadata_sha256":hash(format!("{R}/frozen-{label}.json")),"link_receipt_sha256":hash(format!("{R}/link-{label}.json"))}));}
let candidate=fs::read_to_string(format!("{R}/candidate-disassembly.txt")).unwrap();let calls=candidate.lines().filter(|l|l.contains("call")&&l.contains("coordinate_leaf6finish>")).collect::<Vec<_>>();assert_eq!(calls.len(),1);
let control=read(format!("{R}/control-code.json"));let candidate=read(format!("{R}/candidate-code.json"));let cf=candidate["functions"].as_array().unwrap().iter().filter(|v|v["symbol"].as_str().unwrap().contains("3msm11g2_borrowed")).collect::<Vec<_>>();assert_eq!(cf.len(),2);assert_eq!(cf.iter().map(|f|f["ifma"].as_u64().unwrap()).sum::<u64>(),control["functions"][0]["ifma"].as_u64().unwrap());
for(p,h)in read(format!("{R}/build-pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}
let ledger="/home/ubuntu/src/zopro-perf-work/ibs-backing177/proof-sha256-after-profile.json";assert_eq!(hash(ledger),"4f86193860e35d6f16a765ab2aac7cbff561b747928a73f56a153d86a3cc202d");
let result=json!({"passed":true,"original_files":176,"unchanged_original_files":174,"all_originals_recover":true,"changed_files":changes,"native_core_tests":130,"native_prover_unit_tests":2,"native_cubic_tests":6,"portable_core_tests":97,"verified_workflow_commands":commands,"consumers":consumers,"selected_symbol_sizes":sizes,"candidate_coordinate_call_sites":calls,"total_selected_IFMA_sites":1450,"code_counts_include_alignment_padding":true,"candidate_code":cf,"control_code":control["functions"][0],"SDK_requests":0,"new_exports":0,"canonical_count":52972,"canonical_sha256":hash(ledger),"performance":"unmeasured","adopted":false,"native_helper_sha256":hash(format!("{R}/native-helper"))});
fs::write(format!("{R}/build-review.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();fs::write(format!("{R}/checkpoint.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("PASS130core+2prover+6cubic+97portable;176originalsrecover;intendedSDKcall/1450IFMAs;noSDKlatencyyet");}
